import json

solution = [[0]*15 for _ in range(15)]

# Border = 3
for i in range(2, 11):
    for j in range(3, 12):
        solution[i][j] = 3

# Fill interior with concentric layers
for i in range(3, 10):
    for j in range(4, 11):
        d_left = i - 3
        d_right = 9 - i
        d_top = j - 4
        d_bottom = 10 - j
        dist = max(d_left, d_right, d_top, d_bottom)

        if dist % 2 == 0:
            solution[i][j] = 4
        else:
            solution[i][j] = 2

result = json.dumps(solution)
